                problem = $"exception {e.GetType().Name}: {e.Message}";
            }

            if (problem is not null && ++count <= MaxReported)
                failures.AppendLine($"Dépôt {notes}, {account}, stock {stock}, bloquée {jammed?.ToString() ?? "aucune"} : {problem}");
        }

